import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"晉","description":"周易集解 - 晉","frontmatter":{"title":"晉","description":"周易集解 - 晉"},"headers":[],"relativePath":"classics/jijie/035.md","filePath":"classics/jijie/035.md"}'),l={name:"classics/jijie/035.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="晉" tabindex="-1">晉 <a class="header-anchor" href="#晉" aria-label="Permalink to “晉”">​</a></h1><h2 id="晉-1" tabindex="-1">晉 <a class="header-anchor" href="#晉-1" aria-label="Permalink to “晉”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>晉，康侯用錫馬蕃庶，晝日三接。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物不可以終壯，故受之以晉。晉者，進也。</p><p>崔憬曰：不可以終壯於陽盛，自取觸藩，當宜柔進而上行，受茲錫馬。</p><p>虞翻曰：觀四之五。晉，進也。坤為康。康，安也；初動體屯，震為侯，故曰康侯。震為馬，坤為用，故用錫馬。艮為多，坤為眾，故繁庶。離日在上，故晝日。三陰在下，故三接矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：晉，進也。明出地上，順而麗乎大明。柔進而上行，是以康侯用錫馬蕃庶。晝日三接也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：觀四之五。晉，進也。坤為康。康，安也；初動體屯，震為侯，故曰康侯。震為馬，坤為用，故用錫馬。艮為多，坤為眾，故繁庶。離日在上，故晝日。三陰在下，故三接矣。</p><p>崔憬曰：渾天之義，日從地出，而升於天，故曰明出地上。坤，臣道也。日，君德也。臣以功進，君以恩接，是以順而麗乎大明。雖一卦名，晉而五爻為主，故言柔進而上行也。</p><p>蜀才曰：此本觀卦。案：九五降四，六四進五，是柔進。</p><p>荀爽曰：陰進居五，處用事之位。陽中之陰，侯之象也。陰性安靜，故曰康侯。馬，謂四也。五以下，群陰錫四也。坤為眾，故曰蕃庶矣。</p><p>侯果曰：康，美也。四為諸侯，五為天子，坤為眾，坎為馬。天子至明於上，公侯謙順於下，美其治物有功。故蕃錫車馬，一晝三覿也。《採菽》刺幽王侮諸侯詩曰：雖無與之，路車乘馬。《大行人職》曰：諸公：三饗，三問，三勞；諸侯：三饗，再問，再勞；子男：三饗、一問、一勞，即天子三接諸侯之禮也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：明出地上。晉。君子以自昭明德。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>鄭玄曰：地雖生萬物，日出於上，其功乃著，故君子法之，而｢以明自昭其德｣。</p><p>虞翻曰：君子謂觀乾。乾為德，坤為自，離為明。乾五動，已離日自照，故以自昭明德也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，晉如，摧如，貞吉。罔孚，裕無咎。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：晉，進。摧，憂愁也。應在四，故晉如。失位，故摧如。動得位，故貞吉。應離為罔，四坎稱孚，坤弱為裕，欲四之五成巽，初受其命，故無咎矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：晉如，摧如，獨行正也。裕無咎，未受命也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：初動震為行。初一稱獨也。</p><p>虞翻曰：五未之巽，故未受命也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，晉如，愁如，貞吉。受茲介福於其王母。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：坎為應，在坎上，故愁如。得位處中，故貞吉也。</p><p>虞翻曰：乾為介福，艮為手，坤為虛，故稱受。介，大也。謂五已正中，乾為王，坤為母。故受茲介福於其王母。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：受茲介福，以中正也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：五動得正中，故二受大福矣。大福，謂馬與蕃庶之物是也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，眾允，悔亡。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：坤為眾。允，信也。土性信，故眾允。三失正，與上易位，則悔亡，故《象》曰｢上行也｣。此則成小過，小過故有飛鳥之象焉。臼杵之利，見鼫鼠出入坎穴，蓋取諸此也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：眾允之志，上行也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坎為志。三之上成震，故曰上行也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，晉如鼫鼠，貞厲。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>《九家易》曰：鼫鼠，喻貪，謂四也。體離欲升，體坎欲降。遊不度瀆，不出坎也。飛不上屋，不至上也。緣不極木，不出離也。穴不掩身，五坤薄也。走不先足，外震在下也。五伎皆劣，四爻當之。故曰晉如鼫鼠也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鼫鼠貞厲，位不當也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>翟元曰：鼫鼠晝伏夜行，貪猥無已。謂雖進承五，然潛據下陰，久居不正之位，故有危厲也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，悔亡，矢得勿恤，往吉，無不利。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>荀爽曰：五從坤動而來為離。離者，射出。故曰｢矢得｣。陰居尊位，故有悔也。以中盛明，光照四海，故｢悔亡勿恤，吉無不利｣也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：矢得勿恤，往有慶也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：動之乾，乾為慶也。矢古誓字。誓，信也。勿，無。卹，憂也。五變得正，坎象不見，故｢誓得勿卹，往有慶也｣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，晉其角，惟用伐邑，厲吉無咎，貞吝。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：五已變之乾，為首。位在首上，稱角。故晉其角也。</p><p>虞翻曰：坤為邑。動成震，而體師象，坎為心。故維用伐邑。得位乘五，故｢厲吉，無咎｣而｢貞吝｣矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：惟用伐邑，道未光也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：陽雖在上，動入冥逸，故道未光也。</p>',72)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
